template:
struct Seconds(u32);

impl From<u32> for Seconds {
    fn from(s: u32) -> ⟦slot1⟧ {
        Seconds(s)
    }
}

fn main() {
    let total: Seconds = ⟦slot2⟧;
    assert_eq!(total.0, 60);
}

tests:
#[test]
fn test_from_into() {
    let s: Seconds = 120_u32.into();
    assert_eq!(s.0, 120);
}
